CREATE OR REPLACE FUNCTION public.report_quote(_uid uuid,_key text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.report_prices;s public.subscriptions;r text;q timestamptz;n int:=0;used int:=0;free boolean;BEGIN IF auth.uid() IS NOT NULL AND auth.uid()<>_uid AND auth.role()<>'service_role' THEN RAISE EXCEPTION 'Not your account';END IF;SELECT * INTO p FROM public.report_prices WHERE report_key=_key;IF NOT FOUND THEN RAISE EXCEPTION 'Report unavailable';END IF;r:=public.account_role_of(_uid);SELECT * INTO s FROM public.subscriptions WHERE user_id=_uid AND status='active' AND term_start<=now() AND (term_end IS NULL OR term_end>now()) ORDER BY term_start DESC LIMIT 1;IF s.id IS NOT NULL THEN q:=public.report_quarter_start(s.term_start);SELECT pr.free_per_quarter INTO n FROM public.plan_reports pr JOIN public.plans pl ON pl.id=pr.plan_id WHERE pr.plan_id=s.plan_id AND pr.report_key=_key AND pl.role=r;IF r='buyer' THEN SELECT count(DISTINCT ref) INTO used FROM public.plan_usage WHERE user_id=_uid AND kind='report:'||_key AND term_start=q;ELSE SELECT count(*) INTO used FROM public.plan_usage WHERE user_id=_uid AND kind='report:'||_key AND term_start=q;END IF;END IF;n:=coalesce(n,0);free:=p.price_type='free' AND (p.free_until IS NULL OR p.free_until>=(now() AT TIME ZONE 'Asia/Bangkok')::date) AND CASE r WHEN 'seller' THEN p.free_for_sellers WHEN 'buyer' THEN p.free_for_buyers ELSE false END;RETURN jsonb_build_object('price',p.price_thb,'priceType',p.price_type,'freeUntil',p.free_until,'freePeriod',free,'total',n,'left',greatest(0,n-used),'quarterStart',q,'method',CASE WHEN free THEN 'Free period' WHEN n>used THEN 'Plan' WHEN p.price_type='on_request' THEN 'Quote' ELSE 'Manual' END,'amount',CASE WHEN free OR n>used THEN 0 WHEN p.price_type='on_request' THEN NULL ELSE round(p.price_thb*1.07,2) END);END $$;
REVOKE ALL ON FUNCTION public.report_quote(uuid,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.report_quote(uuid,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.plan_report_quarter_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record;old_n integer;k text;v integer;delta jsonb:='{}';BEGIN FOR r IN SELECT key,value FROM jsonb_each(NEW.changes) LOOP IF r.value->'new' ? 'free_per_quarter' THEN k:=r.key;v:=(r.value->'new'->>'free_per_quarter')::integer;IF NOT EXISTS(SELECT 1 FROM public.report_prices WHERE report_key=k) OR v NOT BETWEEN 0 AND 20 THEN RAISE EXCEPTION 'Invalid quarterly report allowance';END IF;SELECT free_per_quarter INTO old_n FROM public.plan_reports WHERE plan_id=NEW.plan_id AND report_key=k;UPDATE public.plan_reports SET free_per_quarter=v WHERE plan_id=NEW.plan_id AND report_key=k;IF old_n IS DISTINCT FROM v THEN INSERT INTO public.report_price_history(report_key,by_user,summary,changes) SELECT k,NEW.by_user,'Free · '||name||': '||coalesce(old_n,0)||' → '||v||' a quarter',jsonb_build_object('plan',NEW.plan_id,'old',old_n,'new',v) FROM public.plans WHERE id=NEW.plan_id;delta:=delta||jsonb_build_object(k,v);END IF;END IF;END LOOP;IF delta<>'{}'::jsonb THEN INSERT INTO public.security_events(user_id,event_type,details) VALUES(NEW.by_user,'ROLE_CHANGE',jsonb_build_object('action','plan_report_allowances','plan',NEW.plan_id,'changes',delta));END IF;RETURN NEW;END $$;
CREATE TRIGGER plan_report_quarter_saved AFTER INSERT ON public.plan_history FOR EACH ROW EXECUTE FUNCTION public.plan_report_quarter_guard();
CREATE OR REPLACE FUNCTION public.apply_scheduled_pricing() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.apply_scheduled_plan_changes();PERFORM public.apply_scheduled_report_changes();END $$;
REVOKE ALL ON FUNCTION public.apply_scheduled_pricing() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.apply_scheduled_pricing() TO service_role;
SELECT cron.schedule('apply-scheduled-plans-bangkok-midnight','0 17 * * *','select public.apply_scheduled_pricing();');